from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    best = []
    best_color = None
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for yy, xx in ((y-1,x), (y+1,x), (y,x-1), (y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            if len(component) > len(best):
                best, best_color = component, color
    out = [[bg for _ in range(w)] for _ in range(h)]
    r0, r1 = min(r for r, c in best), max(r for r, c in best)
    c0, c1 = min(c for r, c in best), max(c for r, c in best)
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            out[r][c] = best_color
    return out
